const bootScreen = document.getElementById('bootScreen');
const bootLog = document.getElementById('bootLog');
const bootProgressBar = document.getElementById('bootProgressBar');
const bootPercent = document.getElementById('bootPercent');
const bootAccess = document.getElementById('bootAccess');

function startBootSequence() {
  const steps = [
    ['Pokretanje GIS modula...', 16],
    ['Učitavanje kartografskih slojeva...', 39],
    ['Povezivanje sa bazom predmeta K-0426/26...', 64],
    ['Provera korisničkih ovlašćenja...', 86],
    ['Sistem spreman.', 100]
  ];
  steps.forEach((step, index) => {
    setTimeout(() => {
      const line = document.createElement('div');
      line.textContent = step[0];
      bootLog.appendChild(line);
      bootProgressBar.style.width = `${step[1]}%`;
      bootPercent.textContent = `${step[1]}%`;
      if (step[1] === 100) {
        setTimeout(() => bootAccess.classList.remove('hidden'), 250);
        setTimeout(() => {
          bootScreen.classList.add('finished');
          document.body.classList.remove('booting');
          setTimeout(() => map.invalidateSize(), 300);
        }, 1200);
      }
    }, 350 + index * 430);
  });
}

window.addEventListener('load', startBootSequence);

const locationInput = document.getElementById('locationInput');
const searchBtn = document.getElementById('searchBtn');
const searchStatus = document.getElementById('searchStatus');
const resultCard = document.getElementById('resultCard');
const focusCrimeScene = document.getElementById('focusCrimeScene');
const sceneModal = document.getElementById('sceneModal');
const registerEvidence = document.getElementById('registerEvidence');
const downloadPhoto = document.getElementById('downloadPhoto');
const embeddedPhotoData = 'data:image/png;base64,';
const downloadNotice = document.getElementById('downloadNotice');
const evidenceNotice = document.getElementById('evidenceNotice');
const cursorCoords = document.getElementById('cursorCoords');

const sceneCoords = [44.3118, 20.5324];
const map = L.map('mapViewport', {
  center: [44.3075, 20.5265],
  zoom: 14,
  minZoom: 10,
  maxZoom: 19,
  zoomControl: true,
  attributionControl: true
});

L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
  maxZoom: 19,
  attribution: 'Imagery © Esri',
  noWrap: true
}).addTo(map);

const crimeIcon = L.divIcon({
  className: 'crime-icon-wrap',
  html: '<span class="crime-pulse"></span><span class="crime-pin">!</span>',
  iconSize: [48, 48],
  iconAnchor: [24, 43],
  popupAnchor: [0, -40]
});

let crimeMarker = null;

function normalize(text) {
  return text.toLowerCase().trim().replace(/\s+/g, ' ').replace(',', '.');
}

function isCorrectSearch(raw) {
  const q = normalize(raw);
  const compact = q.replace(/\s/g, '');
  return q.includes('veliki vis') || q.includes('vv-07') || q.includes('vv 07') ||
    q.includes('severna padina') ||
    (compact.includes('44.3118') && compact.includes('20.5324')) ||
    (compact.includes('443118') && compact.includes('205324'));
}

function popupHtml() {
  return `<div class="crime-popup-inner">
    <div class="popup-header"><span class="alert-dot"></span>Evidentirana lokacija</div>
    <h3>Mesto pronalaska tela</h3>
    <p>Šumski sektor VV-07</p>
    <div class="popup-meta"><span>24.04.2026.</span><span>06:42</span></div>
    <button id="openSceneBtn" type="button">Otvori uviđaj</button>
  </div>`;
}

function ensureMarker() {
  if (crimeMarker) return;
  crimeMarker = L.marker(sceneCoords, { icon: crimeIcon }).addTo(map).bindPopup(popupHtml(), {
    closeButton: true,
    className: 'crime-leaflet-popup',
    maxWidth: 270
  });
  crimeMarker.on('popupopen', () => {
    document.getElementById('openSceneBtn')?.addEventListener('click', openScene);
  });
}

function focusOnCrimeScene(openPopup = true) {
  ensureMarker();
  map.flyTo(sceneCoords, 18, { duration: 1.4 });
  if (openPopup) setTimeout(() => crimeMarker.openPopup(), 1500);
}

function revealLocation() {
  ensureMarker();
  resultCard.classList.remove('hidden');
  searchStatus.className = 'status success';
  searchStatus.textContent = 'Lokacija pronađena: sektor VV-07.';
  focusOnCrimeScene(true);
}

function runSearch() {
  const value = locationInput.value;
  if (!value.trim()) {
    searchStatus.className = 'status error';
    searchStatus.textContent = 'Unesite naziv lokacije ili koordinate.';
    return;
  }
  searchStatus.className = 'status searching';
  searchStatus.textContent = 'Pretraga policijske baze i GIS slojeva...';
  setTimeout(() => {
    if (isCorrectSearch(value)) revealLocation();
    else {
      searchStatus.className = 'status error';
      searchStatus.textContent = 'Nema evidentirane lokacije za uneseni pojam.';
    }
  }, 800);
}

function triggerPhotoDownload() {
  // Garantovano preuzimanje i kada je projekat otvoren direktno sa računara (file://).
  const link = document.createElement('a');
  link.href = embeddedPhotoData;
  link.download = 'Slika_pronadjenog_tela.png';
  link.style.display = 'none';
  document.body.appendChild(link);
  link.click();
  link.remove();
  downloadNotice.classList.remove('hidden');
}

function openScene() {
  sceneModal.classList.remove('hidden');
  document.body.classList.add('modal-open');
  document.body.style.overflow = 'hidden';
  if (crimeMarker) crimeMarker.closePopup();
  triggerPhotoDownload();
}

searchBtn.addEventListener('click', runSearch);
locationInput.addEventListener('keydown', e => { if (e.key === 'Enter') runSearch(); });
focusCrimeScene.addEventListener('click', () => focusOnCrimeScene(true));

map.on('mousemove', e => {
  cursorCoords.textContent = `${e.latlng.lat.toFixed(4)} N · ${e.latlng.lng.toFixed(4)} E`;
});

map.on('tileerror', () => {
  searchStatus.className = 'status error';
  searchStatus.textContent = 'Satelitski snimak nije učitan. Proverite internet vezu.';
});

function closeScene() {
  sceneModal.classList.add('hidden');
  document.body.classList.remove('modal-open');
  document.body.style.overflow = '';
}

document.querySelectorAll('[data-close-modal]').forEach(el => el.addEventListener('click', closeScene));

document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && !sceneModal.classList.contains('hidden')) {
    closeScene();
  }
});

downloadPhoto.addEventListener('click', triggerPhotoDownload);

registerEvidence.addEventListener('click', () => {
  evidenceNotice.classList.remove('hidden');
  registerEvidence.textContent = 'Evidentirano';
  registerEvidence.disabled = true;
  localStorage.setItem('gisEvidencePhoto01', 'registered');
});

if (localStorage.getItem('gisEvidencePhoto01') === 'registered') {
  evidenceNotice.classList.remove('hidden');
  registerEvidence.textContent = 'Evidentirano';
  registerEvidence.disabled = true;
}

setTimeout(() => map.invalidateSize(), 150);
